-- Plan « PMA et VO2max, récup en aéro » (4 semaines) : 14 séances,
-- objectif aéro et indicateur de réussite (passages en TT validés) par séance.
-- Textes en 9 langues assemblés depuis des gabarits par type. Rejouable.

WITH tpl(typ, lang, name, obj, info) AS (VALUES

('e_cont', 'fr', 'Endurance TT {n}×{d}', 'Tenir la position TT en endurance (65-72 % FTP), sans se relever pendant les blocs. Réussite : {k} passages en TT validés (≥ 95 % du passage en TT, aucune sortie de 20 s ou plus).', 'Endurance fondamentale en position TT : intensité facile pour que toute l''attention aille à la tenue (tête basse, épaules relâchées, appui stable). Les blocs s''allongent d''une semaine à l''autre.'),
('e_cont', 'en', 'TT endurance {n}×{d}', 'Hold the TT position at endurance pace (65-72% FTP) without sitting up during the blocks. Success: {k} TT blocks validated (≥ 95% of the block in TT, no exit of 20 s or more).', 'Base endurance in the TT position: easy intensity so all your attention goes to holding it (head low, shoulders relaxed, stable support). The blocks get longer every week.'),
('e_cont', 'es', 'Resistencia TT {n}×{d}', 'Mantener la posición TT a ritmo de resistencia (65-72 % FTP) sin incorporarte en los bloques. Éxito: {k} tramos en TT validados (≥ 95 % del tramo en TT, ninguna salida de 20 s o más).', 'Resistencia básica en posición TT: intensidad suave para que toda la atención vaya a mantenerla (cabeza baja, hombros relajados, apoyo estable). Los bloques se alargan cada semana.'),
('e_cont', 'it', 'Resistenza TT {n}×{d}', 'Tenere la posizione TT a ritmo di resistenza (65-72 % FTP) senza rialzarti nei blocchi. Riuscita: {k} tratti in TT validati (≥ 95 % del tratto in TT, nessuna uscita di 20 s o più).', 'Resistenza di base in posizione TT: intensità facile perché l''attenzione vada tutta alla tenuta (testa bassa, spalle rilassate, appoggio stabile). I blocchi si allungano ogni settimana.'),
('e_cont', 'de', 'TT-Ausdauer {n}×{d}', 'Die TT-Position im Grundlagentempo (65-72 % FTP) halten, ohne dich in den Blöcken aufzurichten. Erfolg: {k} TT-Abschnitte bestanden (≥ 95 % des Abschnitts in TT, kein Verlassen von 20 s oder mehr).', 'Grundlagenausdauer in TT-Position: leichte Intensität, damit die ganze Aufmerksamkeit dem Halten gilt (Kopf tief, Schultern locker, stabile Auflage). Die Blöcke werden jede Woche länger.'),
('e_cont', 'nl', 'TT-duur {n}×{d}', 'De TT-houding vasthouden op duurtempo (65-72 % FTP) zonder overeind te komen tijdens de blokken. Geslaagd: {k} TT-stukken gehaald (≥ 95 % van het stuk in TT, geen uitstap van 20 s of langer).', 'Basisduur in TT-houding: lichte intensiteit zodat al je aandacht naar het vasthouden gaat (hoofd laag, schouders ontspannen, stabiele steun). De blokken worden elke week langer.'),
('e_cont', 'pt', 'Resistência TT {n}×{d}', 'Manter a posição TT em ritmo de resistência (65-72 % FTP) sem levantar o tronco nos blocos. Sucesso: {k} trechos em TT validados (≥ 95 % do trecho em TT, nenhuma saída de 20 s ou mais).', 'Resistência de base na posição TT: intensidade leve para que toda a atenção vá para mantê-la (cabeça baixa, ombros relaxados, apoio estável). Os blocos ficam mais longos a cada semana.'),
('e_cont', 'ja', 'TT持久 {n}×{d}', '持久ペース（65〜72 % FTP）でTTポジションを保ち、ブロック中は起き上がらない。 達成条件：TTブロック{k}本を達成（ブロックの95 %以上をTTで、20秒以上の離脱なし）。', 'TTポジションでの基礎持久力：強度は楽にして保つことに集中（頭を低く、肩の力を抜き、安定した支え）。ブロックは週ごとに長くなります。'),
('e_cont', 'tr', 'TT dayanıklılık {n}×{d}', 'Dayanıklılık temposunda (%65-72 FTP) TT pozisyonunu koru, bloklarda doğrulma. Başarı: {k} TT bölümü onaylandı (bölümün ≥ %95''i TT''de, 20 sn veya daha uzun çıkış yok).', 'TT pozisyonunda temel dayanıklılık: tüm dikkatin pozisyonu korumakta olsun diye kolay yoğunluk (baş aşağıda, omuzlar gevşek, sabit destek). Bloklar her hafta uzar.'),
('e_long', 'fr', 'Fond TT {m}''', 'Accumuler le plus long temps en TT de la semaine à 70-72 % FTP. Réussite : {k} passages en TT validés (≥ 95 % du passage en TT, aucune sortie de 20 s ou plus).', 'Sortie longue : de longs blocs en TT entrecoupés de courtes pauses redressées. Cherche une position que tu peux tenir, pas la plus basse.'),
('e_long', 'en', 'Long TT ride {m}''', 'Build up the longest TT time of the week at 70-72% FTP. Success: {k} TT blocks validated (≥ 95% of the block in TT, no exit of 20 s or more).', 'Long ride: long TT blocks broken up by short upright breaks. Find a position you can hold, not the lowest one.'),
('e_long', 'es', 'Fondo TT {m}''', 'Acumular el mayor tiempo en TT de la semana al 70-72 % FTP. Éxito: {k} tramos en TT validados (≥ 95 % del tramo en TT, ninguna salida de 20 s o más).', 'Salida larga: bloques largos en TT con pausas cortas erguido. Busca una posición que puedas mantener, no la más baja.'),
('e_long', 'it', 'Fondo TT {m}''', 'Accumulare il tempo in TT più lungo della settimana al 70-72 % FTP. Riuscita: {k} tratti in TT validati (≥ 95 % del tratto in TT, nessuna uscita di 20 s o più).', 'Uscita lunga: lunghi blocchi in TT con brevi pause eretto. Cerca una posizione che puoi tenere, non la più bassa.'),
('e_long', 'de', 'Lange TT-Fahrt {m}''', 'Die längste TT-Zeit der Woche bei 70-72 % FTP sammeln. Erfolg: {k} TT-Abschnitte bestanden (≥ 95 % des Abschnitts in TT, kein Verlassen von 20 s oder mehr).', 'Lange Fahrt: lange TT-Blöcke mit kurzen aufrechten Pausen. Such eine Position, die du halten kannst, nicht die tiefste.'),
('e_long', 'nl', 'Lange TT-rit {m}''', 'De langste TT-tijd van de week opbouwen op 70-72 % FTP. Geslaagd: {k} TT-stukken gehaald (≥ 95 % van het stuk in TT, geen uitstap van 20 s of langer).', 'Lange rit: lange TT-blokken met korte pauzes rechtop. Zoek een houding die je kunt volhouden, niet de laagste.'),
('e_long', 'pt', 'Fundo TT {m}''', 'Acumular o maior tempo em TT da semana a 70-72 % FTP. Sucesso: {k} trechos em TT validados (≥ 95 % do trecho em TT, nenhuma saída de 20 s ou mais).', 'Treino longo: blocos longos em TT com pausas curtas ereto. Procure uma posição que consiga manter, não a mais baixa.'),
('e_long', 'ja', 'ロングTT {m}''', '70〜72 % FTPで週で最も長いTT時間を積み上げる。 達成条件：TTブロック{k}本を達成（ブロックの95 %以上をTTで、20秒以上の離脱なし）。', 'ロングライド：短いアップライト休憩を挟んだ長いTTブロック。一番低い姿勢ではなく、維持できる姿勢を探して。'),
('e_long', 'tr', 'Uzun TT sürüş {m}''', '%70-72 FTP''de haftanın en uzun TT süresini biriktir. Başarı: {k} TT bölümü onaylandı (bölümün ≥ %95''i TT''de, 20 sn veya daha uzun çıkış yok).', 'Uzun sürüş: kısa dik molalarla bölünmüş uzun TT blokları. En alçak değil, koruyabileceğin bir pozisyon bul.'),
('v_3015', 'fr', 'PMA 30/15 {n}×{d} + TT', 'Reprendre la position TT en moins de 5 s après chaque effort de 30 s et la garder sur les 15 s de récupération. Réussite : {k} passages en TT validés (≥ 95 % du passage en TT, aucune sortie de 20 s ou plus).', 'Le 30/15 de Rønnestad garde la consommation d''oxygène haute plus longtemps qu''un intervalle long. Effort en position libre, les 15 s de récupération en TT ; pause redressée entre les séries, bloc final en TT.'),
('v_3015', 'en', 'VO2max 30/15 {n}×{d} + TT', 'Get back into TT within 5 s after each 30 s effort and keep it through the 15 s recovery. Success: {k} TT blocks validated (≥ 95% of the block in TT, no exit of 20 s or more).', 'Rønnestad''s 30/15 keeps oxygen uptake high longer than a long interval. Effort in any position, the 15 s recovery in TT; upright break between sets, final block in TT.'),
('v_3015', 'es', 'VO2max 30/15 {n}×{d} + TT', 'Volver al TT en menos de 5 s tras cada esfuerzo de 30 s y mantenerlo durante los 15 s de recuperación. Éxito: {k} tramos en TT validados (≥ 95 % del tramo en TT, ninguna salida de 20 s o más).', 'El 30/15 de Rønnestad mantiene alto el consumo de oxígeno más tiempo que un intervalo largo. Esfuerzo en posición libre, los 15 s de recuperación en TT; pausa erguido entre series, bloque final en TT.'),
('v_3015', 'it', 'VO2max 30/15 {n}×{d} + TT', 'Riprendere la posizione TT entro 5 s da ogni sforzo di 30 s e tenerla nei 15 s di recupero. Riuscita: {k} tratti in TT validati (≥ 95 % del tratto in TT, nessuna uscita di 20 s o più).', 'Il 30/15 di Rønnestad mantiene alto il consumo di ossigeno più a lungo di un intervallo lungo. Sforzo in posizione libera, i 15 s di recupero in TT; pausa eretto tra le serie, blocco finale in TT.'),
('v_3015', 'de', 'VO2max 30/15 {n}×{d} + TT', 'Nach jeder 30-s-Belastung binnen 5 s zurück in TT und die 15 s Erholung darin bleiben. Erfolg: {k} TT-Abschnitte bestanden (≥ 95 % des Abschnitts in TT, kein Verlassen von 20 s oder mehr).', 'Rønnestads 30/15 hält die Sauerstoffaufnahme länger hoch als ein langes Intervall. Belastung in freier Position, die 15 s Erholung in TT; aufrechte Pause zwischen den Serien, Schlussblock in TT.'),
('v_3015', 'nl', 'VO2max 30/15 {n}×{d} + TT', 'Binnen 5 s na elke inspanning van 30 s terug in TT en die houden tijdens de 15 s herstel. Geslaagd: {k} TT-stukken gehaald (≥ 95 % van het stuk in TT, geen uitstap van 20 s of langer).', 'De 30/15 van Rønnestad houdt de zuurstofopname langer hoog dan een lang interval. Inspanning in vrije houding, de 15 s herstel in TT; pauze rechtop tussen de series, slotblok in TT.'),
('v_3015', 'pt', 'VO2max 30/15 {n}×{d} + TT', 'Voltar ao TT em menos de 5 s após cada esforço de 30 s e mantê-lo nos 15 s de recuperação. Sucesso: {k} trechos em TT validados (≥ 95 % do trecho em TT, nenhuma saída de 20 s ou mais).', 'O 30/15 de Rønnestad mantém o consumo de oxigênio alto por mais tempo que um intervalo longo. Esforço em posição livre, os 15 s de recuperação em TT; pausa ereto entre as séries, bloco final em TT.'),
('v_3015', 'ja', 'VO2max 30/15 {n}×{d} + TT', '30秒の努力のたびに5秒以内にTTへ戻り、15秒の回復の間保つ。 達成条件：TTブロック{k}本を達成（ブロックの95 %以上をTTで、20秒以上の離脱なし）。', 'Rønnestadの30/15は長いインターバルより長く酸素摂取量を高く保ちます。努力はポジション自由、15秒の回復はTTで。セット間は起き上がって休憩、最後のブロックはTT。'),
('v_3015', 'tr', 'VO2max 30/15 {n}×{d} + TT', 'Her 30 sn''lik efordan sonra 5 sn içinde TT''ye dön ve 15 sn''lik toparlanma boyunca koru. Başarı: {k} TT bölümü onaylandı (bölümün ≥ %95''i TT''de, 20 sn veya daha uzun çıkış yok).', 'Rønnestad''ın 30/15''i oksijen tüketimini uzun bir intervalden daha uzun süre yüksek tutar. Efor serbest pozisyonda, 15 sn''lik toparlanma TT''de; setler arasında dik mola, son blok TT''de.'),
('v_44', 'fr', 'PMA {n}×{d} + TT', 'Rester en position TT pendant chaque récupération de PMA et sur le bloc final à 70 % FTP, souffle court compris. Réussite : {k} passages en TT validés (≥ 95 % du passage en TT, aucune sortie de 20 s ou plus).', 'Intervalles longs de PMA (format 4×4'' de Helgerud) en position libre ; chaque récupération et le bloc final à 70 % FTP se font en TT, pour apprendre à rester bas quand le souffle est court.'),
('v_44', 'en', 'VO2max {n}×{d} + TT', 'Stay in the TT position during every VO2max recovery and the final block at 70% FTP, even when out of breath. Success: {k} TT blocks validated (≥ 95% of the block in TT, no exit of 20 s or more).', 'Long VO2max intervals (Helgerud''s 4×4'' format) in any position; every recovery and the final block at 70% FTP are in TT, to learn to stay low when you''re out of breath.'),
('v_44', 'es', 'VO2max {n}×{d} + TT', 'Mantener la posición TT en cada recuperación de VO2max y en el bloque final al 70 % FTP, aun sin aliento. Éxito: {k} tramos en TT validados (≥ 95 % del tramo en TT, ninguna salida de 20 s o más).', 'Intervalos largos de VO2max (formato 4×4'' de Helgerud) en posición libre; cada recuperación y el bloque final al 70 % FTP se hacen en TT, para aprender a seguir abajo sin aliento.'),
('v_44', 'it', 'VO2max {n}×{d} + TT', 'Restare in posizione TT in ogni recupero di VO2max e nel blocco finale al 70 % FTP, anche col fiato corto. Riuscita: {k} tratti in TT validati (≥ 95 % del tratto in TT, nessuna uscita di 20 s o più).', 'Intervalli lunghi di VO2max (formato 4×4'' di Helgerud) in posizione libera; ogni recupero e il blocco finale al 70 % FTP si fanno in TT, per imparare a restare bassi col fiato corto.'),
('v_44', 'de', 'VO2max {n}×{d} + TT', 'In jeder VO2max-Erholung und im Schlussblock bei 70 % FTP in TT-Position bleiben, auch wenn die Luft knapp ist. Erfolg: {k} TT-Abschnitte bestanden (≥ 95 % des Abschnitts in TT, kein Verlassen von 20 s oder mehr).', 'Lange VO2max-Intervalle (4×4''-Format nach Helgerud) in freier Position; jede Erholung und der Schlussblock bei 70 % FTP in TT, um tief zu bleiben, wenn die Luft knapp ist.'),
('v_44', 'nl', 'VO2max {n}×{d} + TT', 'In TT-houding blijven tijdens elk VO2max-herstel en het slotblok op 70 % FTP, ook als je adem tekortkomt. Geslaagd: {k} TT-stukken gehaald (≥ 95 % van het stuk in TT, geen uitstap van 20 s of langer).', 'Lange VO2max-intervallen (4×4''-formaat van Helgerud) in vrije houding; elk herstel en het slotblok op 70 % FTP in TT, om laag te leren blijven als je adem tekortkomt.'),
('v_44', 'pt', 'VO2max {n}×{d} + TT', 'Ficar na posição TT em cada recuperação de VO2max e no bloco final a 70 % FTP, mesmo sem fôlego. Sucesso: {k} trechos em TT validados (≥ 95 % do trecho em TT, nenhuma saída de 20 s ou mais).', 'Intervalos longos de VO2max (formato 4×4'' de Helgerud) em posição livre; cada recuperação e o bloco final a 70 % FTP são em TT, para aprender a ficar baixo sem fôlego.'),
('v_44', 'ja', 'VO2max {n}×{d} + TT', '息が苦しくても、VO2maxの回復と最後の70 % FTPブロックではTTポジションを保つ。 達成条件：TTブロック{k}本を達成（ブロックの95 %以上をTTで、20秒以上の離脱なし）。', 'ロングVO2maxインターバル（Helgerudの4×4''形式）をポジション自由で。回復と最後の70 % FTPブロックはTTで、息が苦しいときも低く保つ練習。'),
('v_44', 'tr', 'VO2max {n}×{d} + TT', 'Nefesin kesik olsa da her VO2max toparlanmasında ve %70 FTP''deki son blokta TT pozisyonunda kal. Başarı: {k} TT bölümü onaylandı (bölümün ≥ %95''i TT''de, 20 sn veya daha uzun çıkış yok).', 'Serbest pozisyonda uzun VO2max intervalleri (Helgerud 4×4'' formatı); her toparlanma ve %70 FTP''deki son blok TT''de, nefes kesikken alçakta kalmayı öğrenmek için.')
), wk(lang, p) AS (VALUES ('fr', 'S'), ('en', 'W'), ('es', 'S'), ('it', 'S'), ('de', 'W'), ('nl', 'W'), ('pt', 'S'), ('ja', 'W'), ('tr', 'H')
), s(skey, typ, week, n, d, minutes, k, aero, blocks, lc) AS (VALUES

