('vo2_tt_4w_w1s3', 'e_cont', 1, '2', '15''', 51, 2, 1800, '[{"type": "Grad+", "unit": "% FTP", "power_start": 50.0, "power_end": 75.0, "duration_work": 600}, {"type": "FRAC", "unit": "% FTP", "power_start": 70.0, "power_end": 70.0, "duration_work": 900, "duration_recup": 180, "repetitions": 2, "position": "prolongateurs", "position_recup": "cocottes"}, {"type": "Grad-", "unit": "% FTP", "power_start": 65.0, "power_end": 45.0, "duration_work": 300}]'::jsonb, '[{"at": 590, "key": "vo2_tt_4w_lc_start", "duration": 12}, {"at": 1500, "key": "vo2_tt_4w_lc_up", "duration": 10}, {"at": 1670, "key": "vo2_tt_4w_lc_start", "duration": 12}, {"at": 2580, "key": "vo2_tt_4w_lc_up", "duration": 10}]'::jsonb),
