('vo2_tt_4w_w4s2', 'v_3015', 4, '2', '13', 47, 27, 990, '[{"type": "Grad+", "unit": "% FTP", "power_start": 50.0, "power_end": 75.0, "duration_work": 600}, {"type": "FRAC", "unit": "% FTP", "power_start": 120.0, "power_end": 50.0, "duration_work": 30, "duration_recup": 15, "repetitions": 13, "position_recup": "prolongateurs"}, {"type": "CONST", "unit": "% FTP", "power_start": 50.0, "duration_work": 180}, {"type": "FRAC", "unit": "% FTP", "power_start": 120.0, "power_end": 50.0, "duration_work": 30, "duration_recup": 15, "repetitions": 13, "position_recup": "prolongateurs"}, {"type": "CONST", "unit": "% FTP", "power_start": 70.0, "duration_work": 600, "position": "prolongateurs"}, {"type": "Grad-", "unit": "% FTP", "power_start": 65.0, "power_end": 45.0, "duration_work": 300}]'::jsonb, '[{"at": 630, "key": "vo2_tt_4w_lc_recup", "duration": 12}]'::jsonb),
('vo2_tt_4w_w4s3', 'e_cont', 4, '1', '40''', 55, 1, 2400, '[{"type": "Grad+", "unit": "% FTP", "power_start": 50.0, "power_end": 75.0, "duration_work": 600}, {"type": "CONST", "unit": "% FTP", "power_start": 70.0, "duration_work": 2400, "position": "prolongateurs"}, {"type": "Grad-", "unit": "% FTP", "power_start": 65.0, "power_end": 45.0, "duration_work": 300}]'::jsonb, '[{"at": 590, "key": "vo2_tt_4w_lc_start", "duration": 12}, {"at": 1800, "key": "vo2_tt_4w_lc_mid", "duration": 12}]'::jsonb)
), built AS (
  SELECT s.*,
    (SELECT jsonb_object_agg(t.lang, wk.p || s.week || ' · ' || replace(replace(replace(replace(t.name, '{n}', s.n), '{d}', s.d), '{m}', s.minutes::text), ' 1×', ' '))
       FROM tpl t JOIN wk USING (lang) WHERE t.typ = s.typ) AS names,
    (SELECT jsonb_object_agg(t.lang, replace(t.obj, '{k}', s.k::text)) FROM tpl t WHERE t.typ = s.typ) AS objs,
    (SELECT jsonb_object_agg(t.lang, t.info) FROM tpl t WHERE t.typ = s.typ) AS infos
  FROM s
)
INSERT INTO public.training_sessions (name, info, objectif, session_json, total_duration, is_test, live_comments, translations_json, aero_duration_sec)
SELECT b.skey || '_name', b.skey || '_info', b.skey || '_objectif',
  jsonb_build_object('nom', b.names ->> 'fr', 'infos', '', 'duration', b.minutes, 'UnitDisplay', '% FTP', 'blocks', b.blocks),
  b.minutes, false, b.lc,
  jsonb_build_object('name', b.names, 'objectif', b.objs, 'info', b.infos, 'live_comments', '{"vo2_tt_4w_lc_start": {"fr": "Passe en TT sur les prolongateurs : épaules relâchées, tiens jusqu''au bout du bloc.", "en": "Get into TT on the extensions: shoulders relaxed, hold until the end of the block.", "es": "Ponte en TT en los acoples: hombros relajados, aguanta hasta el final del bloque.", "it": "Mettiti in TT sulle protesi: spalle rilassate, tieni fino alla fine del blocco.", "de": "Ab in TT auf den Aufsatz: Schultern locker, bis zum Ende des Blocks halten.", "nl": "Ga in TT op de opzetstukken: schouders ontspannen, houd vol tot het einde van het blok.", "pt": "Vá para o TT no clipe: ombros relaxados, aguente até o fim do bloco.", "ja": "エアロバーでTTに：肩の力を抜き、ブロックの最後まで維持しよう。", "tr": "Uzatmalarda TT''ye geç: omuzlar gevşek, blok bitene kadar koru."}, "vo2_tt_4w_lc_up": {"fr": "Relève-toi et récupère. Prochain bloc en TT.", "en": "Sit up and recover. Next block in TT.", "es": "Incorpórate y recupera. Próximo bloque en TT.", "it": "Rialzati e recupera. Prossimo blocco in TT.", "de": "Aufrichten und erholen. Nächster Block in TT.", "nl": "Kom overeind en herstel. Volgend blok in TT.", "pt": "Levante o tronco e recupere. Próximo bloco em TT.", "ja": "上体を起こして回復。次のブロックはTTで。", "tr": "Doğrul ve toparlan. Sonraki blok TT''de."}, "vo2_tt_4w_lc_mid": {"fr": "Mi-bloc : vérifie ta tête et tes épaules, reste bas et relâché.", "en": "Halfway: check your head and shoulders, stay low and relaxed.", "es": "Mitad del bloque: revisa cabeza y hombros, sigue abajo y relajado.", "it": "Metà blocco: controlla testa e spalle, resta basso e rilassato.", "de": "Halbzeit: Kopf und Schultern prüfen, tief und locker bleiben.", "nl": "Halverwege: check je hoofd en schouders, blijf laag en ontspannen.", "pt": "Metade do bloco: confira cabeça e ombros, fique baixo e relaxado.", "ja": "ブロックの半分：頭と肩を確認、低くリラックスしたまま。", "tr": "Blok ortası: başını ve omuzlarını kontrol et, alçak ve gevşek kal."}, "vo2_tt_4w_lc_recup": {"fr": "Récupère en TT : reste sur les prolongateurs, ton cerveau associe la position au repos.", "en": "Recover in TT: stay on the extensions, your brain links the position with rest.", "es": "Recupera en TT: sigue en los acoples, tu cerebro asocia la posición al descanso.", "it": "Recupera in TT: resta sulle protesi, il cervello associa la posizione al riposo.", "de": "Erhole dich in TT: Bleib auf dem Aufsatz, dein Gehirn verbindet die Position mit Ruhe.", "nl": "Herstel in TT: blijf op de opzetstukken, je brein koppelt de houding aan rust.", "pt": "Recupere em TT: fique no clipe, seu cérebro associa a posição ao descanso.", "ja": "TTで回復：エアロバーに乗ったまま。脳がこの姿勢を休息と結びつけます。", "tr": "TT''de toparlan: uzatmalarda kal, beynin pozisyonu dinlenmeyle ilişkilendirir."}}'::jsonb),
  b.aero
FROM built b
WHERE NOT EXISTS (SELECT 1 FROM public.training_sessions ts WHERE ts.name = b.skey || '_name');

INSERT INTO public.training_plans (name_key, description_key, objective_key, duration_weeks, difficulty, plan_type, sessions_per_week, is_active, translations_json)
SELECT 'vo2_tt_4w_name', 'vo2_tt_4w_description', 'vo2_tt_4w_objective', 4, 'advanced', 'training', 4, true, '{"name": {"fr": "PMA et VO2max, récup en aéro", "en": "VO2max, recovery in aero", "es": "VO2max, recuperación en aero", "it": "VO2max, recupero in aero", "de": "VO2max, Erholung in Aero", "nl": "VO2max, herstel in aero", "pt": "VO2max, recuperação em aero", "ja": "VO2max、回復はエアロ", "tr": "VO2max, aero''da toparlanma"}, "objective": {"fr": "Faire monter ta PMA et ta VO2max, et apprendre à rester en TT quand le souffle est court.", "en": "Raise your VO2max and learn to stay in TT when you''re out of breath.", "es": "Subir tu VO2max y aprender a mantenerte en TT sin aliento.", "it": "Alzare il VO2max e imparare a restare in TT col fiato corto.", "de": "VO2max steigern und lernen, in TT zu bleiben, wenn die Luft knapp ist.", "nl": "Je VO2max verhogen en leren in TT te blijven als je adem tekortkomt.", "pt": "Aumentar seu VO2max e aprender a ficar em TT sem fôlego.", "ja": "VO2maxを高め、息が苦しくてもTTを保てるようになる。", "tr": "VO2max''ını yükselt ve nefesin kesikken TT''de kalmayı öğren."}, "description": {"fr": "4 semaines, 3 à 4 séances de 45 à 75 minutes. Intervalles longs de PMA (4 à 6 × 4'', 112-118 % FTP) et séries de 30/15 (120 % FTP) en position libre ; chaque récupération et chaque bloc final à 70 % FTP se font en TT. Une séance d''endurance TT par semaine.", "en": "4 weeks, 3 to 4 sessions of 45 to 75 minutes. Long VO2max intervals (4 to 6 × 4'', 112-118% FTP) and 30/15 sets (120% FTP) in any position; every recovery and every final block at 70% FTP is in TT. One TT endurance session a week.", "es": "4 semanas, 3 a 4 sesiones de 45 a 75 minutos. Intervalos largos de VO2max (4 a 6 × 4'', 112-118 % FTP) y series 30/15 (120 % FTP) en posición libre; cada recuperación y cada bloque final al 70 % FTP se hacen en TT. Una sesión de resistencia TT por semana.", "it": "4 settimane, da 3 a 4 sessioni da 45 a 75 minuti. Intervalli lunghi di VO2max (da 4 a 6 × 4'', 112-118 % FTP) e serie 30/15 (120 % FTP) in posizione libera; ogni recupero e ogni blocco finale al 70 % FTP si fanno in TT. Una sessione di resistenza TT a settimana.", "de": "4 Wochen, 3 bis 4 Einheiten von 45 bis 75 Minuten. Lange VO2max-Intervalle (4 bis 6 × 4'', 112-118 % FTP) und 30/15-Serien (120 % FTP) in freier Position; jede Erholung und jeder Schlussblock bei 70 % FTP in TT. Eine TT-Ausdauereinheit pro Woche.", "nl": "4 weken, 3 tot 4 sessies van 45 tot 75 minuten. Lange VO2max-intervallen (4 tot 6 × 4'', 112-118 % FTP) en 30/15-series (120 % FTP) in vrije houding; elk herstel en elk slotblok op 70 % FTP in TT. Eén TT-duursessie per week.", "pt": "4 semanas, 3 a 4 sessões de 45 a 75 minutos. Intervalos longos de VO2max (4 a 6 × 4'', 112-118 % FTP) e séries 30/15 (120 % FTP) em posição livre; cada recuperação e cada bloco final a 70 % FTP são em TT. Uma sessão de resistência TT por semana.", "ja": "4週間、45〜75分のセッションを週3〜4回。ロングVO2maxインターバル（4〜6×4''、112〜118 % FTP）と30/15（120 % FTP）はポジション自由、回復と最後の70 % FTPブロックはすべてTT。週1回のTT持久セッション。", "tr": "4 hafta, haftada 45-75 dakikalık 3-4 seans. Serbest pozisyonda uzun VO2max intervalleri (4-6 × 4'', %112-118 FTP) ve 30/15 setleri (%120 FTP); her toparlanma ve %70 FTP''deki her son blok TT''de. Haftada bir TT dayanıklılık seansı."}}'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.training_plans WHERE name_key = 'vo2_tt_4w_name');

INSERT INTO public.plan_sessions (plan_id, training_session_id, week_number, session_number)
SELECT p.id, ts.id, v.week, v.num
FROM (VALUES (1, 1, 'vo2_tt_4w_w1s1_name'), (1, 2, 'vo2_tt_4w_w1s2_name'), (1, 3, 'vo2_tt_4w_w1s3_name'), (2, 1, 'vo2_tt_4w_w2s1_name'), (2, 2, 'vo2_tt_4w_w2s2_name'), (2, 3, 'vo2_tt_4w_w2s3_name'), (2, 4, 'vo2_tt_4w_w2s4_name'), (3, 1, 'vo2_tt_4w_w3s1_name'), (3, 2, 'vo2_tt_4w_w3s2_name'), (3, 3, 'vo2_tt_4w_w3s3_name'), (3, 4, 'vo2_tt_4w_w3s4_name'), (4, 1, 'vo2_tt_4w_w4s1_name'), (4, 2, 'vo2_tt_4w_w4s2_name'), (4, 3, 'vo2_tt_4w_w4s3_name')) AS v(week, num, session_name)
JOIN public.training_sessions ts ON ts.name = v.session_name
JOIN public.training_plans p ON p.name_key = 'vo2_tt_4w_name'
WHERE NOT EXISTS (SELECT 1 FROM public.plan_sessions ps WHERE ps.plan_id = p.id AND ps.training_session_id = ts.id);
